def find_peak(arr, n):
    """Write a function to find the peak element in the given array."""
    if n <= 0 or not arr:
        return -1
    if n == 1:
        return 0
    if len(arr) < n:
        n = len(arr)
    if arr[0] >= arr[1]:
        return 0
    if arr[n - 1] >= arr[n - 2]:
        return n - 1
    low, high = 1, n - 2
    while low <= high:
        mid = (low + high) // 2
        left = arr[mid - 1]
        right = arr[mid + 1]
        if arr[mid] >= left and arr[mid] >= right:
            return mid
        elif arr[mid - 1] > arr[mid]:
            high = mid - 1
        else:
            low = mid + 1
    return -1
